# -*- coding: UTF-8 -*-
"""Domain models for IP/host scanning."""


class Host:
    """Represents a host (domain) to be scanned."""
    def __init__(self, name):
        self.name = name.strip()

    def __str__(self):
        return self.name

    def __repr__(self):
        return f"Host({self.name!r})"


class ScanTarget:
    """Represents a scan target: (host, ip)."""
    def __init__(self, host, ip):
        self.host = Host(host) if isinstance(host, str) else host
        self.ip = ip.strip() if isinstance(ip, str) else ip

    def __str__(self):
        return f"{self.ip} -> {self.host}"

    def __repr__(self):
        return f"ScanTarget(host={self.host!r}, ip={self.ip!r})"
